/* A concept slot is "written" when a concept declares that subcategory.
   Everything else is visible structure — shown honestly, never faked. */
/* A slot is filled when a concept declares that subcategory. Some concepts
   are known by a different label than the slot they belong to, so those are
   mapped explicitly. This makes the map independent of how any single concept
   happens to be labelled. */
const SLOT_ALIASES = {
  "corporate|Cost of Capital": "cost-of-capital",
  "corporate|WACC": "wacc",
  "corporate|Discounted Cash Flow": "free-cash-flow",
  "corporate|Free Cash Flow": "fcf-detail",
  "corporate|NPV": "discount-rate",
  "corporate|Leverage": "leverage",
};

const conceptForSlot = (domainId, sub) => {
  const direct = CONCEPTS.find((c) => c.domain === domainId && c.subcategory === sub);
  if (direct) return direct;
  const aliased = SLOT_ALIASES[`${domainId}|${sub}`];
  return aliased ? CONCEPTS.find((c) => c.id === aliased) : undefined;
};

const domainStats = (d) => {
  const cats = d.categories || [];
  const slots = cats.reduce((n, c) => n + c.subcategories.length, 0);
  const written = cats.reduce((n, c) =>
    n + c.subcategories.filter((s) => conceptForSlot(d.id, s)).length, 0);
  return { slots, written };
};

const conceptById = (id) => CONCEPTS.find((c) => c.id === id);

