function Marquee({ hash }) {
  const reduced = useReducedMotion();
  const [paused, setPaused] = useState(false);
  const here = (h) => hash === h || hash.startsWith(h + "/");

  const strip = (key) => (
    <div className="mq-run" key={key} aria-hidden={key === "b" ? "true" : undefined}>
      {MARQUEE.map((m) => (
        <a className={"mq-item" + (here(m.href) ? " on" : "")} key={key + m.href} href={m.href}
          tabIndex={key === "b" ? -1 : 0}>
          <span className="mq-dot" />
          <span className="mq-n">{m.name}</span>
          <span className="mq-note">{m.note}</span>
        </a>
      ))}
    </div>
  );

  return (
    <div className={"mq" + (paused || reduced ? " paused" : "")}
      onMouseEnter={() => setPaused(true)} onMouseLeave={() => setPaused(false)}
      onTouchStart={() => setPaused(true)}
      role="navigation" aria-label="Everything in FinHub">
      <div className="mq-track">{strip("a")}{strip("b")}</div>
    </div>
  );
}

