/* One relationship explorer, used on the landing page and the graph page.
   Selecting a concept changes the map, and the map is the navigation. */
function GraphExplorer({ initial = "inflation", showOpen = true }) {
  const [focus, setFocus] = useState(initial);
  const c = conceptById(focus) || CONCEPTS[0];

  /* A curated set of entry points rather than whichever concepts happen to sit
     first in the array. These are the ones with the richest connections, so
     the map has something to show from the first moment. */
  const picks = useMemo(() => {
    const want = ["inflation", "time-value-of-money", "compounding", "interest-rates",
      "risk-return", "leverage", "diversification", "equity", "bond-pricing",
      "options", "futures", "monetary-policy", "balance-sheet", "cash-flow-statement",
      "financial-ratios", "cost-of-capital", "free-cash-flow", "working-capital",
      "credit-risk", "liquidity-risk", "market-liquidity", "central-banking",
      "commercial-banking", "digital-payments"];
    const found = want.map(conceptById).filter(Boolean);
    if (found.length >= 12) return found;
    return CONCEPTS.filter((x) => (x.related || []).length >= 3).slice(0, 24);
  }, []);

  return (
    <div className="explorer">
      <div className="explorer-picker" role="tablist" aria-label="Choose a concept">
        {picks.map((x) => (
          <button key={x.id} role="tab" aria-selected={focus === x.id}
            className={"tab" + (focus === x.id ? " on" : "")} onClick={() => setFocus(x.id)}>
            {x.title}
          </button>
        ))}
      </div>
      <div className="card stage explorer-map">
        <ConceptGraph id={c.id} key={c.id} />
      </div>
      {showOpen && (
        <div className="explorer-foot">
          <p className="small" style={{ maxWidth: "52ch" }}>{c.oneLine}</p>
          <a className="btn ghost" href={`#/concept/${c.id}`}>Open {c.title} →</a>
        </div>
      )}
    </div>
  );
}

function GraphPage() {
  return (
    <>
      <Crumbs items={[["FinHub", "#/"], ["Knowledge graph"]]} />
      <div className="wrap" style={{ paddingBottom: 110 }}>
        <Reveal><h1 className="h-page">The knowledge graph</h1></Reveal>
        <Reveal delay={70}>
          <p className="lede" style={{ marginTop: 18, maxWidth: "56ch" }}>
            {CONCEPTS.length} concepts and {EDGES.length} recorded relationships. Choose a concept
            to see what it touches, then select any node to move to it.
          </p>
        </Reveal>
        <div style={{ marginTop: 48 }}><GraphExplorer initial="inflation" /></div>
      </div>
    </>
  );
}

/* ===========================================================================
   GLOSSARY
   =========================================================================== */

function Glossary() {
  const [q, setQ] = useState("");
  const list = GLOSSARY.filter((g) =>
    (g.term + " " + g.def + " " + g.simple).toLowerCase().includes(q.trim().toLowerCase()));
  return (
    <>
      <Crumbs items={[["FinHub", "#/"], ["Glossary"]]} />
      <div className="wrap-n" style={{ paddingBottom: 110 }}>
        <Reveal><h1 className="h-page">Glossary</h1></Reveal>
        <Reveal delay={70}>
          <p className="lede" style={{ marginTop: 18 }}>
            The precise definition, then the same idea in plain words, then the route into the
            concept behind it.
          </p>
        </Reveal>

        <div className="field" style={{ marginTop: 30, maxWidth: 440 }}>
          <label htmlFor="gq">Filter terms</label>
          <input id="gq" value={q} onChange={(e) => setQ(e.target.value)} placeholder="e.g. duration" />
        </div>

        <p className="small" style={{ marginBottom: 10 }}>
          {list.length} {list.length === 1 ? "term" : "terms"}
        </p>

        {list.length === 0 && (
          <p className="body" style={{ paddingTop: 20 }}>No term matches “{q}”.</p>
        )}

        <div className="gloss">
          {list.map((g, i) => (
            <Reveal key={g.term} delay={Math.min(i * 30, 200)}>
              <div className="gloss-item">
                <h2 className="gloss-term">{g.term}</h2>
                <div style={{ minWidth: 0 }}>
                  <p className="gloss-def">{g.def}</p>
                  <p className="gloss-simple">{g.simple}</p>
                  {g.formula && <div className="gloss-f">{g.formula}</div>}
                  {conceptById(g.link) && (
                    <div>
                      <a className="gloss-link" href={`#/concept/${g.link}`}>
                        {conceptById(g.link).title} →
                      </a>
                    </div>
                  )}
                </div>
              </div>
            </Reveal>
          ))}
        </div>
      </div>
    </>
  );
}

/* ===========================================================================
   TOOLS — every calculator is real arithmetic
   =========================================================================== */

const fmt = (n, d = 0) => isFinite(n)
  ? n.toLocaleString("en-IN", { minimumFractionDigits: d, maximumFractionDigits: d })
  : "—";

/* ===========================================================================
   CONCEPT SIMULATORS
   A concept gets one only when moving a number teaches something a sentence
   cannot. Each is real arithmetic — the same formulas printed above it — and
   redraws live as the input moves.
   =========================================================================== */

function Slider({ label, value, set, min, max, step = 1, suffix = "" }) {
  return (
    <div className="sl">
      <div className="sl-top">
        <label htmlFor={label}>{label}</label>
        <b>{value}{suffix}</b>
      </div>
      <input id={label} type="range" min={min} max={max} step={step} value={value}
        onChange={(e) => set(Number(e.target.value))} />
    </div>
  );
}

/* 1 — COMPOUNDING: the curve against the straight line */
function SimCompounding() {
  const [rate, setRate] = useState(8);
  const [years, setYears] = useState(20);
  const P = 100000;
  const W = 640, H = 260, pad = 34;

  const pts = [];
  for (let t = 0; t <= years; t++) {
    pts.push({ t, comp: P * Math.pow(1 + rate / 100, t), simple: P * (1 + (rate / 100) * t) });
  }
  const maxV = Math.max(pts[pts.length - 1].comp, 1);
  const X = (t) => pad + (t / Math.max(years, 1)) * (W - pad * 2);
  const Y = (v) => H - pad - (v / maxV) * (H - pad * 2);
  const line = (k) => pts.map((p, i) => `${i ? "L" : "M"}${X(p.t).toFixed(1)} ${Y(p[k]).toFixed(1)}`).join(" ");

  const final = pts[pts.length - 1];
  const gap = final.comp - final.simple;

  return (
    <div className="sim">
      <div className="sim-controls">
        <Slider label="Annual rate" value={rate} set={setRate} min={1} max={20} suffix="%" />
        <Slider label="Years" value={years} set={setYears} min={1} max={40} />
      </div>
      <svg viewBox={`0 0 ${W} ${H}`} className="sim-svg" role="img"
        aria-label={`Growth of one lakh at ${rate} percent over ${years} years`}>
        <line x1={pad} y1={H - pad} x2={W - pad} y2={H - pad} className="sim-axis" />
        <line x1={pad} y1={pad} x2={pad} y2={H - pad} className="sim-axis" />
        <path d={line("simple")} className="sim-line simple" />
        <path d={line("comp")} className="sim-line comp" />
        <circle cx={X(years)} cy={Y(final.comp)} r="5" className="sim-dot comp" />
        <circle cx={X(years)} cy={Y(final.simple)} r="4" className="sim-dot simple" />
      </svg>
      <div className="sim-out">
        <div><span>Simple interest</span><b>₹{fmt(final.simple)}</b></div>
        <div><span>Compounded</span><b className="hi">₹{fmt(final.comp)}</b></div>
        <div><span>Earned on interest alone</span><b className="hi">₹{fmt(gap)}</b></div>
      </div>
      <p className="sim-note">
        The straight line is interest paid only on the original ₹1,00,000. The curve adds
        interest earned on interest. The space between them is compounding.
      </p>
    </div>
  );
}

/* 2 — LEVERAGE: how far a fall in asset values eats equity */
function SimLeverage() {
  const [debtPct, setDebtPct] = useState(60);
  const [fall, setFall] = useState(10);
  const assets = 10000000;
  const debt = assets * (debtPct / 100);
  const equity0 = assets - debt;
  const assets1 = assets * (1 - fall / 100);
  const equity1 = assets1 - debt;
  const wiped = equity0 > 0 ? Math.min(100, Math.max(0, ((equity0 - equity1) / equity0) * 100)) : 100;
  const insolvent = equity1 <= 0;

  return (
    <div className="sim">
      <div className="sim-controls">
        <Slider label="Funded by debt" value={debtPct} set={setDebtPct} min={0} max={90} suffix="%" />
        <Slider label="Fall in asset values" value={fall} set={setFall} min={0} max={50} suffix="%" />
      </div>

      <div className="bs">
        <div className="bs-col">
          <p className="bs-h">Assets</p>
          <div className="bs-bar">
            <div className="bs-fill assets" style={{ height: `${(assets1 / assets) * 100}%` }} />
            <div className="bs-lost" style={{ height: `${fall}%` }} />
          </div>
          <p className="bs-v">₹{fmt(assets1)}</p>
        </div>
        <div className="bs-col">
          <p className="bs-h">Funded by</p>
          <div className="bs-bar">
            <div className="bs-fill equity" style={{ height: `${Math.max(0, (equity1 / assets) * 100)}%` }}>
              <span>Equity</span>
            </div>
            <div className="bs-fill debt" style={{ height: `${(debt / assets) * 100}%` }}>
              <span>Debt</span>
            </div>
          </div>
          <p className="bs-v">{insolvent ? "Equity exhausted" : `Equity ₹${fmt(equity1)}`}</p>
        </div>
      </div>

      <div className="sim-out">
        <div><span>Equity before</span><b>₹{fmt(equity0)}</b></div>
        <div><span>Equity after</span><b className={insolvent ? "bad" : "hi"}>{insolvent ? "₹0" : `₹${fmt(equity1)}`}</b></div>
        <div><span>Share of equity wiped out</span><b className={wiped > 60 ? "bad" : "hi"}>{fmt(wiped, 1)}%</b></div>
      </div>
      <p className="sim-note">
        Debt does not move when asset values fall. The entire loss lands on equity, which is why
        a {fall}% fall in assets removes {fmt(wiped, 1)}% of the owners’ position at this level of leverage.
      </p>
    </div>
  );
}

/* 3 — BOND PRICING: why price and yield move in opposite directions */
function SimBond() {
  const [coupon, setCoupon] = useState(6);
  const [yieldPct, setYield] = useState(8);
  const [years, setYears] = useState(5);
  const F = 1000;
  const price = (() => {
    const y = yieldPct / 100, c = F * (coupon / 100);
    let p = 0;
    for (let t = 1; t <= years; t++) p += c / Math.pow(1 + y, t);
    return p + F / Math.pow(1 + y, years);
  })();
  const pct = ((price - F) / F) * 100;
  const W = 640, H = 200, pad = 32;
  const curve = [];
  for (let yv = 1; yv <= 16; yv += 0.5) {
    const y = yv / 100, c = F * (coupon / 100);
    let p = 0;
    for (let t = 1; t <= years; t++) p += c / Math.pow(1 + y, t);
    p += F / Math.pow(1 + y, years);
    curve.push({ yv, p });
  }
  const maxP = Math.max(...curve.map((d) => d.p)), minP = Math.min(...curve.map((d) => d.p));
  const X = (yv) => pad + ((yv - 1) / 15) * (W - pad * 2);
  const Y = (p) => H - pad - ((p - minP) / Math.max(1, maxP - minP)) * (H - pad * 2);

  return (
    <div className="sim">
      <div className="sim-controls three">
        <Slider label="Coupon" value={coupon} set={setCoupon} min={0} max={15} step={0.5} suffix="%" />
        <Slider label="Market yield" value={yieldPct} set={setYield} min={1} max={16} step={0.5} suffix="%" />
        <Slider label="Years to maturity" value={years} set={setYears} min={1} max={30} />
      </div>
      <svg viewBox={`0 0 ${W} ${H}`} className="sim-svg" role="img"
        aria-label={`Bond price against yield, ${coupon} percent coupon`}>
        <line x1={pad} y1={Y(F)} x2={W - pad} y2={Y(F)} className="sim-axis dash" />
        <text x={W - pad} y={Y(F) - 8} textAnchor="end" className="sim-lab">Face value ₹1,000</text>
        <path d={curve.map((d, i) => `${i ? "L" : "M"}${X(d.yv).toFixed(1)} ${Y(d.p).toFixed(1)}`).join(" ")}
          className="sim-line comp" />
        <circle cx={X(yieldPct)} cy={Y(price)} r="6" className="sim-dot comp" />
      </svg>
      <div className="sim-out">
        <div><span>Price today</span><b className="hi">₹{fmt(price, 2)}</b></div>
        <div><span>Against face value</span><b className={pct < 0 ? "bad" : "hi"}>{pct >= 0 ? "+" : ""}{fmt(pct, 1)}%</b></div>
        <div><span>Trading at</span><b>{price > F ? "a premium" : price < F ? "a discount" : "par"}</b></div>
      </div>
      <p className="sim-note">
        The coupon never changes. When the market demands a higher yield, the only thing that can
        move is the price — and the longer the maturity, the further it has to fall.
      </p>
    </div>
  );
}


/* --- Options payoff: the line bends at the strike ---------------------- */
function SimOptions() {
  const [kind, setKind] = useState("call");
  const [strike, setStrike] = useState(22000);
  const [premium, setPremium] = useState(200);
  const [side, setSide] = useState("buy");
  const lot = 50;
  const W = 640, H = 260, pad = 40;
  const lo = strike * 0.94, hi = strike * 1.06;

  const payoff = (spot) => {
    const intrinsic = kind === "call"
      ? Math.max(spot - strike, 0)
      : Math.max(strike - spot, 0);
    const net = intrinsic - premium;
    return side === "buy" ? net : -net;
  };

  const pts = [];
  for (let i = 0; i <= 60; i++) {
    const spot = lo + ((hi - lo) * i) / 60;
    pts.push({ spot, p: payoff(spot) });
  }
  const maxAbs = Math.max(...pts.map((d) => Math.abs(d.p)), premium * 1.6);
  const X = (spot) => pad + ((spot - lo) / (hi - lo)) * (W - pad * 2);
  const Y = (p) => H / 2 - (p / maxAbs) * (H / 2 - pad);
  const path = pts.map((d, i) => `${i ? "L" : "M"}${X(d.spot).toFixed(1)} ${Y(d.p).toFixed(1)}`).join(" ");

  const breakeven = kind === "call" ? strike + premium : strike - premium;
  const maxLoss = side === "buy" ? premium * lot : Infinity;
  const maxGain = side === "buy"
    ? (kind === "call" ? Infinity : (strike - premium) * lot)
    : premium * lot;

  return (
    <div className="sim">
      <div className="art-tabs">
        <button className={"tab" + (kind === "call" ? " on" : "")} onClick={() => setKind("call")}>Call</button>
        <button className={"tab" + (kind === "put" ? " on" : "")} onClick={() => setKind("put")}>Put</button>
        <button className={"tab" + (side === "buy" ? " on" : "")} onClick={() => setSide("buy")}>Buy</button>
        <button className={"tab" + (side === "sell" ? " on" : "")} onClick={() => setSide("sell")}>Sell</button>
      </div>

      <div className="sim-controls">
        <Slider label="Strike" value={strike} set={setStrike} min={20000} max={24000} step={100} />
        <Slider label="Premium" value={premium} set={setPremium} min={20} max={600} step={10} suffix=" ₹" />
      </div>

      <svg viewBox={`0 0 ${W} ${H}`} className="sim-svg" role="img"
        aria-label={`Payoff of a ${side} ${kind} at strike ${strike}`}>
        <rect x={pad} y={pad} width={W - pad * 2} height={H / 2 - pad} className="pay-zone up" />
        <rect x={pad} y={H / 2} width={W - pad * 2} height={H / 2 - pad} className="pay-zone down" />
        <line x1={pad} y1={H / 2} x2={W - pad} y2={H / 2} className="sim-axis" />
        <line x1={X(strike)} y1={pad} x2={X(strike)} y2={H - pad} className="sim-axis dash" />
        <text x={X(strike)} y={H - pad + 16} textAnchor="middle" className="mv-lab">Strike</text>
        <line x1={X(breakeven)} y1={pad} x2={X(breakeven)} y2={H - pad} className="pay-be" />
        <text x={X(breakeven)} y={pad - 8} textAnchor="middle" className="pay-be-t">Breakeven</text>
        <path d={path} className="pay-line" />
      </svg>

      <div className="sim-out">
        <div><span>Breakeven</span><b className="hi">{fmt(breakeven, 0)}</b></div>
        <div><span>Maximum loss</span>
          <b className={maxLoss === Infinity ? "bad" : ""}>{maxLoss === Infinity ? "Unlimited" : `₹${fmt(maxLoss)}`}</b></div>
        <div><span>Maximum gain</span>
          <b className="hi">{maxGain === Infinity ? "Unlimited" : `₹${fmt(maxGain)}`}</b></div>
      </div>
      <p className="sim-note">
        Lot size 50. A bought option loses only the premium at worst, which is what the premium buys.
        A sold option collects the premium and carries the obligation, so the payoff is the mirror image.
        Being right about direction is not enough: the move must clear the breakeven.
      </p>
    </div>
  );
}

/* --- Diversification: correlation is the whole story ------------------- */
function SimDiversification() {
  const [corr, setCorr] = useState(0.6);
  const [wA, setWA] = useState(60);
  const volA = 18, volB = 12;
  const w1 = wA / 100, w2 = 1 - w1;
  const port = Math.sqrt(
    w1 * w1 * volA * volA + w2 * w2 * volB * volB + 2 * w1 * w2 * corr * volA * volB
  );
  const weighted = w1 * volA + w2 * volB;
  const benefit = weighted - port;

  const W = 620, H = 190, pad = 34;
  const series = (phase, vol) =>
    Array.from({ length: 60 }, (_, i) => {
      const base = Math.sin(i / 5.5) * vol;
      const own = Math.sin(i / 3.1 + phase) * vol * 0.7;
      return base * corr + own * (1 - Math.abs(corr));
    });
  const a = series(0, volA), b = series(2.4, volB);
  const p = a.map((v, i) => w1 * v + w2 * b[i]);
  const scale = 26;
  const line = (arr, yOff) =>
    arr.map((v, i) => `${i ? "L" : "M"}${(pad + (i / 59) * (W - pad * 2)).toFixed(1)} ${(yOff - v * (scale / 18)).toFixed(1)}`).join(" ");

  return (
    <div className="sim">
      <div className="sim-controls">
        <Slider label="Correlation between the two assets" value={corr} set={setCorr} min={-1} max={1} step={0.05} />
        <Slider label="Weight in the riskier asset" value={wA} set={setWA} min={0} max={100} step={5} suffix="%" />
      </div>

      <svg viewBox={`0 0 ${W} ${H}`} className="sim-svg" role="img"
        aria-label="Two assets and the portfolio that combines them">
        <path d={line(a, 45)} className="div-line a" />
        <text x={pad} y={22} className="mv-lab">Asset A, 18% volatility</text>
        <path d={line(b, 105)} className="div-line b" />
        <text x={pad} y={82} className="mv-lab">Asset B, 12% volatility</text>
        <path d={line(p, 165)} className="div-line p" />
        <text x={pad} y={142} className="mv-lab">Combined portfolio</text>
      </svg>

      <div className="sim-out">
        <div><span>Weighted average volatility</span><b>{fmt(weighted, 1)}%</b></div>
        <div><span>Actual portfolio volatility</span><b className="hi">{fmt(port, 1)}%</b></div>
        <div><span>Reduction from diversification</span>
          <b className={benefit > 1 ? "hi" : ""}>{fmt(benefit, 1)} points</b></div>
      </div>
      <p className="sim-note">
        At a correlation of 1 the two assets move together and there is no benefit at all: portfolio
        volatility equals the weighted average. As correlation falls, the movements begin to cancel and the
        combined line flattens. The benefit comes from low correlation, not from the number of holdings.
      </p>
    </div>
  );
}

/* --- SIP against lumpsum, across three market paths -------------------- */
function SimSipLumpsum() {
  const [market, setMarket] = useState("rising");
  const [monthly, setMonthly] = useState(10000);
  const months = 60;
  const total = monthly * months;

  const pathOf = (kind) => {
    const out = [];
    for (let i = 0; i <= months; i++) {
      const t = i / months;
      let nav;
      if (kind === "rising") nav = 100 * (1 + 0.9 * t);
      else if (kind === "falling") nav = 100 * (1 - 0.35 * t);
      else nav = 100 * (1 + 0.25 * t + 0.32 * Math.sin(t * Math.PI * 2.2));
      out.push(nav);
    }
    return out;
  };
  const nav = pathOf(market);

  let units = 0;
  for (let i = 1; i <= months; i++) units += monthly / nav[i];
  const sipValue = units * nav[months];
  const lumpUnits = total / nav[0];
  const lumpValue = lumpUnits * nav[months];

  const W = 620, H = 170, pad = 32;
  const minN = Math.min(...nav), maxN = Math.max(...nav);
  const X = (i) => pad + (i / months) * (W - pad * 2);
  const Y = (v) => H - pad - ((v - minN) / Math.max(1, maxN - minN)) * (H - pad * 2);
  const navPath = nav.map((v, i) => `${i ? "L" : "M"}${X(i).toFixed(1)} ${Y(v).toFixed(1)}`).join(" ");

  return (
    <div className="sim">
      <div className="art-tabs" role="tablist" aria-label="Market path">
        {[["rising", "Rising market"], ["falling", "Falling market"], ["choppy", "Choppy market"]].map(([k, l]) => (
          <button key={k} role="tab" aria-selected={market === k}
            className={"tab" + (market === k ? " on" : "")} onClick={() => setMarket(k)}>{l}</button>
        ))}
      </div>
      <div className="sim-controls">
        <Slider label="Monthly amount" value={monthly} set={setMonthly} min={1000} max={50000} step={1000} suffix=" ₹" />
      </div>

      <svg viewBox={`0 0 ${W} ${H}`} className="sim-svg" role="img" aria-label="Fund value over five years">
        <path d={navPath} className="sim-line comp" />
        {[12, 24, 36, 48].map((m) => (
          <circle key={m} cx={X(m)} cy={Y(nav[m])} r="3" className="sim-dot comp" />
        ))}
      </svg>

      <div className="sim-out">
        <div><span>Total invested</span><b>₹{fmt(total)}</b></div>
        <div><span>Monthly investing</span>
          <b className={sipValue >= lumpValue ? "hi" : ""}>₹{fmt(sipValue)}</b></div>
        <div><span>All at the start</span>
          <b className={lumpValue > sipValue ? "hi" : ""}>₹{fmt(lumpValue)}</b></div>
      </div>
      <p className="sim-note">
        {market === "rising" && "In a market that rises steadily, investing everything at the start wins, because the money is exposed for longer."}
        {market === "falling" && "In a falling market, monthly investing buys more units at lower prices, so it loses less. Neither method produces a gain here."}
        {market === "choppy" && "In a market that moves sideways with large swings, monthly investing accumulates units cheaply during the falls."}
        {" "}The path is illustrative and returns are not constant in reality. What the comparison shows is that the
        advantage of each method depends on the path, and the path is not knowable in advance.
      </p>
    </div>
  );
}


/* ---- Ratio workbench: one set of figures, every ratio recomputed live ---- */
function SimRatios() {
  const [f, setF] = useState({
    revenue: 200, cogs: 140, ebit: 30, interest: 12, tax: 25, net: 18,
    ca: 24, inv: 28, recv: 36, cash: 10, cl: 15, pay: 22,
    assets: 160, debt: 120, equity: 75, price: 840, shares: 0.64,
  });
  const set = (k) => (v) => setF((s) => ({ ...s, [k]: v }));
  const n = (x) => (isFinite(x) ? x : 0);

  const ebitda = f.ebit + 12;
  const capEmployed = f.assets - f.cl;
  const eps = f.shares ? f.net / f.shares : 0;
  const bvps = f.shares ? f.equity / f.shares : 0;

  const groups = [
    { name: "Liquidity", rows: [
      ["Current ratio", n(f.ca / f.cl), 2, "", f.ca / f.cl >= 1 ? "hi" : "bad"],
      ["Quick ratio", n((f.ca - f.inv) / f.cl), 2, "", (f.ca - f.inv) / f.cl >= 1 ? "hi" : "bad"],
      ["Cash ratio", n(f.cash / f.cl), 2, ""],
    ]},
    { name: "Profitability", rows: [
      ["Operating margin", n((f.ebit / f.revenue) * 100), 1, "%"],
      ["Net margin", n((f.net / f.revenue) * 100), 1, "%"],
      ["Return on equity", n((f.net / f.equity) * 100), 1, "%", "hi"],
      ["Return on capital employed", n((f.ebit / capEmployed) * 100), 1, "%"],
    ]},
    { name: "Leverage", rows: [
      ["Debt to equity", n(f.debt / f.equity), 2, ""],
      ["Interest coverage", n(f.ebit / f.interest), 1, "×", f.ebit / f.interest >= 3 ? "hi" : "bad"],
      ["Net debt to EBITDA", n((f.debt - f.cash) / ebitda), 2, ""],
    ]},
    { name: "Efficiency", rows: [
      ["Asset turnover", n(f.revenue / f.assets), 2, "×"],
      ["Inventory days", n((f.inv / f.cogs) * 365), 0, " days"],
      ["Receivable days", n((f.recv / f.revenue) * 365), 0, " days"],
      ["Cash conversion cycle", n((f.inv / f.cogs) * 365 + (f.recv / f.revenue) * 365 - (f.pay / f.cogs) * 365), 0, " days"],
    ]},
    { name: "Valuation", rows: [
      ["Earnings per share", eps, 2, ""],
      ["Price to earnings", n(f.price / eps), 1, "×"],
      ["Price to book", n(f.price / bvps), 2, "×"],
    ]},
  ];

  // DuPont
  const margin = n(f.net / f.revenue), turn = n(f.revenue / f.assets), mult = n(f.assets / f.equity);
  const roe = margin * turn * mult * 100;

  const fields = [
    ["Revenue", "revenue"], ["Cost of goods sold", "cogs"], ["EBIT", "ebit"],
    ["Interest", "interest"], ["Net profit", "net"], ["Current assets", "ca"],
    ["Inventory", "inv"], ["Receivables", "recv"], ["Cash", "cash"],
    ["Current liabilities", "cl"], ["Payables", "pay"], ["Total assets", "assets"],
    ["Total debt", "debt"], ["Equity", "equity"],
  ];

  return (
    <div className="sim">
      <p className="small" style={{ marginBottom: 16 }}>
        One company, in ₹ crore. Change any figure and every ratio recomputes. The point is not the
        arithmetic but watching which ratios disagree with each other.
      </p>
      <div className="rw-fields">
        {fields.map(([label, key]) => (
          <label className="tkf" key={key}>
            <span>{label}</span>
            <input type="number" value={f[key]}
              onChange={(e) => set(key)(Math.max(0, Number(e.target.value)))} />
          </label>
        ))}
      </div>

      <div className="rw-groups">
        {groups.map((g) => (
          <div className="rw-group" key={g.name}>
            <p className="eyebrow" style={{ marginBottom: 10 }}>{g.name}</p>
            {g.rows.map(([label, val, dp, suffix, tone]) => (
              <div className="rw-row" key={label}>
                <span>{label}</span>
                <b className={tone || ""}>{fmt(val, dp)}{suffix}</b>
              </div>
            ))}
          </div>
        ))}
      </div>

      <div className="rw-dupont">
        <p className="eyebrow" style={{ marginBottom: 12 }}>DuPont decomposition of return on equity</p>
        <div className="rw-chain">
          <div><span>Net margin</span><b>{fmt(margin * 100, 1)}%</b></div>
          <em>×</em>
          <div><span>Asset turnover</span><b>{fmt(turn, 2)}×</b></div>
          <em>×</em>
          <div><span>Equity multiplier</span><b className={mult > 2.5 ? "bad" : ""}>{fmt(mult, 2)}×</b></div>
          <em>=</em>
          <div className="rw-res"><span>Return on equity</span><b className="hi">{fmt(roe, 1)}%</b></div>
        </div>
        <p className="sim-note" style={{ marginTop: 14 }}>
          {mult > 2.5
            ? `An equity multiplier of ${fmt(mult, 2)} means a large part of this return comes from borrowing rather than from the business. It works identically in reverse when profits fall.`
            : `With a multiplier of ${fmt(mult, 2)}, this return is coming mainly from the business rather than from leverage.`}
        </p>
      </div>
    </div>
  );
}


/* ---- Payment journey ------------------------------------------------------
   Money as a visible object crossing a system. You press send and watch it
   travel, stop, wait and arrive. The waiting is the lesson, so it is shown
   rather than described.
   -------------------------------------------------------------------------- */

const PAY_ROUTES = {
  upi: {
    name: "UPI", sub: "Domestic, one system", tone: "hi", arrive: "Under 2 seconds",
    stops: [
      { at: "Your app", note: "Instruction signed", wait: 0 },
      { at: "Your bank", note: "PIN verified, account debited", wait: 0 },
      { at: "Central switch", note: "Beneficiary bank identified", wait: 0 },
      { at: "Their bank", note: "Account credited", wait: 0 },
    ],
    line: "One system. One currency. One regulator. Nothing has to be translated on the way.",
  },
  card: {
    name: "Card", sub: "Approval now, money later", tone: "", arrive: "1 to 3 days",
    stops: [
      { at: "Terminal", note: "Authorisation requested", wait: 0 },
      { at: "Your bank", note: "Funds held, not moved", wait: 0 },
      { at: "End of day", note: "Merchant submits the day's sales", wait: 1 },
      { at: "Clearing", note: "Banks calculate what each owes", wait: 1 },
      { at: "Merchant", note: "Credited, less fees", wait: 0 },
    ],
    line: "Approval and settlement are two different events. You saw the first. The money moved during the second.",
  },
  cross: {
    name: "Cross-border", sub: "Several systems, several rules", tone: "bad", arrive: "1 to 5 working days",
    stops: [
      { at: "Your bank", note: "Instruction accepted", wait: 0 },
      { at: "Compliance", note: "Sanctions and source-of-funds checks", wait: 2 },
      { at: "Correspondent", note: "An intermediary bank, taking a fee", wait: 1 },
      { at: "Conversion", note: "Rate applied, with a spread", wait: 1 },
      { at: "Time zone", note: "Their working day has not started", wait: 2 },
      { at: "Their bank", note: "Their own checks, then credited", wait: 1 },
    ],
    line: "Every handover is an institution that must verify again, in its own hours, under its own rules.",
  },
};

function SimPayments() {
  const reduced = useReducedMotion();
  const [route, setRoute] = useState("upi");
  const [at, setAt] = useState(-1);
  const [state, setState] = useState("idle");
  const t = useRef(0);
  const r = PAY_ROUTES[route];
  const n = r.stops.length;

  useEffect(() => { setAt(-1); setState("idle"); clearTimeout(t.current); }, [route]);

  useEffect(() => {
    if (state !== "moving" && state !== "waiting") return;
    const next = at + 1;
    if (next >= n) { setState("done"); return; }
    const w = r.stops[next].wait;
    if (w > 0 && state === "moving") {
      setState("waiting");
      t.current = window.setTimeout(() => { setAt(next); setState("moving"); }, 900 + w * 700);
    } else {
      t.current = window.setTimeout(() => setAt(next), 850);
    }
    return () => clearTimeout(t.current);
  }, [state, at, route]);

  const send = () => { setAt(-1); setState("moving"); };
  const pos = at < 0 ? 0 : ((at + 0.5) / n) * 100;
  const waiting = state === "waiting";

  return (
    <div className="pj">
      <div className="pj-tabs" role="tablist" aria-label="Route">
        {Object.entries(PAY_ROUTES).map(([k, v]) => (
          <button key={k} role="tab" aria-selected={route === k}
            className={"pj-tab" + (route === k ? " on" : "")} onClick={() => setRoute(k)}>
            <b>{v.name}</b><span>{v.arrive}</span>
          </button>
        ))}
      </div>

      <div className="pj-stage">
        {!reduced && (
          <div className="pj-grid" aria-hidden="true">
            {Array.from({ length: 22 }).map((_, i) => (
              <span key={i} style={{ left: `${(i * 37) % 100}%`, animationDelay: `-${(i * 0.8) % 12}s` }} />
            ))}
          </div>
        )}

        <div className="pj-rail">
          <div className="pj-rail-done" style={{ width: `${state === "done" ? 100 : pos}%` }} />
          {r.stops.map((s, i) => {
            const done = i <= at || state === "done";
            const here = i === at + 1 && waiting;
            return (
              <div className={"pj-stop" + (done ? " done" : "") + (here ? " waiting" : "")}
                key={s.at} style={{ left: `${((i + 0.5) / n) * 100}%` }}>
                <span className="pj-node" />
                <span className="pj-at">{s.at}</span>
                {s.wait > 0 && <span className="pj-wait">{s.wait === 1 ? "waits" : "waits longer"}</span>}
              </div>
            );
          })}

          <div className={"pj-money" + (state === "done" ? " arrived" : "") + (waiting ? " held" : "")}
            style={{ left: `${state === "done" ? 100 : pos}%` }}>
            <span className="pj-coin">₹</span>
            {waiting && <span className="pj-hold">held</span>}
          </div>
        </div>

        <div className="pj-status">
          {state === "idle" && <span>Ready to send</span>}
          {state === "moving" && at >= 0 && <span className="mv">{r.stops[at].note}</span>}
          {state === "moving" && at < 0 && <span className="mv">Sending</span>}
          {waiting && <span className="wt">Waiting at {r.stops[Math.min(at + 1, n - 1)].at}</span>}
          {state === "done" && <span className="dn">Arrived · {r.arrive}</span>}
        </div>
      </div>

      <div className="pj-controls">
        <button className="btn primary" onClick={send} disabled={state === "moving" || state === "waiting"}>
          {state === "done" ? "Send again" : "Send ₹1,000"}
        </button>
        <p className="pj-line">{r.line}</p>
      </div>
    </div>
  );
}


/* ---- Inflation: the same sum, losing its buying power ------------------ */
function SimInflation() {
  const [rate, setRate] = useState(6);
  const [years, setYears] = useState(25);
  const amount = 100000;
  const real = amount / Math.pow(1 + rate / 100, years);
  const W = 620, H = 200, pad = 34;
  const pts = Array.from({ length: years + 1 }, (_, y) => ({
    y, v: amount / Math.pow(1 + rate / 100, y),
  }));
  const X = (i) => pad + (i / years) * (W - pad * 2);
  const Y = (v) => H - pad - (v / amount) * (H - pad * 2);
  const line = pts.map((p, i) => `${i ? "L" : "M"}${X(i).toFixed(1)} ${Y(p.v).toFixed(1)}`).join(" ");
  const half = pts.findIndex((p) => p.v <= amount / 2);

  return (
    <div className="sim">
      <Slider label="Inflation rate" value={rate} set={setRate} min={2} max={12} step={0.5} suffix="%" />
      <Slider label="Years" value={years} set={setYears} min={5} max={40} />
      <svg viewBox={`0 0 ${W} ${H}`} className="sim-svg" role="img"
        aria-label="Purchasing power of a fixed sum over time">
        <line x1={pad} y1={Y(amount)} x2={W - pad} y2={Y(amount)} className="sim-axis dash" />
        <text x={pad} y={Y(amount) - 8} className="sim-lab">₹1,00,000 today</text>
        <path d={`${line} L${X(years)} ${H - pad} L${X(0)} ${H - pad} Z`} className="inf-fill" />
        <path d={line} className="inf-line" />
        {half > 0 && (
          <g>
            <line x1={X(half)} y1={pad} x2={X(half)} y2={H - pad} className="inf-half" />
            <text x={X(half) + 6} y={pad + 12} className="sim-lab amber">Half gone by year {half}</text>
          </g>
        )}
        <circle cx={X(years)} cy={Y(real)} r="5" className="sim-dot comp" />
      </svg>
      <div className="sim-out">
        <div><span>Nominal amount</span><b>₹{fmt(amount)}</b></div>
        <div><span>Buys what ₹… buys today</span><b className="bad">₹{fmt(real)}</b></div>
        <div><span>Purchasing power lost</span><b className="bad">{fmt((1 - real / amount) * 100, 1)}%</b></div>
      </div>
      <p className="sim-note">
        The number in the account never changed. At {rate}% for {years} years, ₹1,00,000 buys what
        ₹{fmt(real, 0)} buys today. This is why money held in cash for a long horizon loses
        quietly, without any visible loss ever appearing on a statement.
      </p>
    </div>
  );
}

/* ---- One company, three statements ------------------------------------ */
function SimStatements() {
  const [step, setStep] = useState(0);
  const steps = [
    { t: "The sale is made", inc: "Revenue +₹10,00,000", bs: "Receivables +₹10,00,000", cf: "No cash movement",
      note: "Profit is recorded the moment the sale is made. The customer has 60 days to pay, so no cash has arrived. This is why a profitable company can be short of money." },
    { t: "Costs are incurred", inc: "Cost of goods −₹6,00,000", bs: "Inventory −₹6,00,000", cf: "No cash movement",
      note: "Goods leave inventory and become a cost. Again nothing moves in cash, because the goods were paid for in an earlier period." },
    { t: "Profit appears", inc: "Gross profit ₹4,00,000", bs: "Retained earnings +₹4,00,000", cf: "Still nothing",
      note: "The income statement now shows ₹4,00,000 of profit. The bank balance is unchanged. Both statements are correct." },
    { t: "The customer pays", inc: "No effect", bs: "Receivables −₹10,00,000, Cash +₹10,00,000", cf: "Operating cash +₹10,00,000",
      note: "Sixty days later the cash arrives. The income statement does not move, because the profit was already recognised. Only now does the cash flow statement show anything." },
  ];
  const s = steps[step];
  return (
    <div className="sim">
      <div className="art-tabs">
        {steps.map((x, i) => (
          <button key={i} className={"tab" + (step === i ? " on" : "")} onClick={() => setStep(i)}>
            {String(i + 1).padStart(2, "0")}
          </button>
        ))}
      </div>
      <p className="st-title">{s.t}</p>
      <div className="st-cols">
        <div className={"st-col" + (s.inc !== "No effect" ? " on" : "")}>
          <p className="eyebrow">Income statement</p><b>{s.inc}</b></div>
        <div className={"st-col" + (s.bs ? " on" : "")}>
          <p className="eyebrow">Balance sheet</p><b>{s.bs}</b></div>
        <div className={"st-col" + (s.cf.includes("+") ? " on" : "")}>
          <p className="eyebrow">Cash flow</p><b>{s.cf}</b></div>
      </div>
      <p className="sim-note">{s.note}</p>
    </div>
  );
}

/* ---- Working capital as a turning cycle -------------------------------- */
function SimWorkingCapital() {
  const [inv, setInv] = useState(62);
  const [rec, setRec] = useState(58);
  const [pay, setPay] = useState(45);
  const [rev, setRev] = useState(240);
  const cycle = inv + rec - pay;
  const trapped = (rev * 1e7 / 365) * cycle;
  const R = 62, cx = 100, cy = 88;
  const total = Math.max(1, inv + rec + pay);
  const arc = (from, len, cls) => {
    const a0 = (from / total) * 360 - 90, a1 = ((from + len) / total) * 360 - 90;
    const rad = Math.PI / 180;
    const x0 = cx + R * Math.cos(a0 * rad), y0 = cy + R * Math.sin(a0 * rad);
    const x1 = cx + R * Math.cos(a1 * rad), y1 = cy + R * Math.sin(a1 * rad);
    return <path className={"wc-arc " + cls} d={`M${x0} ${y0} A${R} ${R} 0 ${len / total > 0.5 ? 1 : 0} 1 ${x1} ${y1}`} />;
  };
  return (
    <div className="sim">
      <div className="wc-wrap">
        <svg viewBox="0 0 200 176" className="wc-svg" role="img" aria-label="The working capital cycle">
          <circle cx={cx} cy={cy} r={R} className="wc-track" />
          {arc(0, inv, "inv")}
          {arc(inv, rec, "rec")}
          {arc(inv + rec, pay, "pay")}
          <text x={cx} y={cy - 6} textAnchor="middle" className="wc-big">{cycle}</text>
          <text x={cx} y={cy + 12} textAnchor="middle" className="wc-small">days of cash tied up</text>
        </svg>
        <div className="wc-keys">
          <span><i className="k-inv" /> Inventory {inv} days</span>
          <span><i className="k-rec" /> Receivables {rec} days</span>
          <span><i className="k-pay" /> Payables −{pay} days</span>
        </div>
      </div>
      <Slider label="Inventory days" value={inv} set={setInv} min={10} max={140} />
      <Slider label="Receivable days" value={rec} set={setRec} min={5} max={140} />
      <Slider label="Payable days" value={pay} set={setPay} min={5} max={120} />
      <Slider label="Annual revenue, ₹ crore" value={rev} set={setRev} min={20} max={800} step={10} />
      <div className="sim-out">
        <div><span>Cash conversion cycle</span><b className={cycle > 90 ? "bad" : "hi"}>{cycle} days</b></div>
        <div><span>Cash tied up</span><b>₹{fmt(trapped / 1e7, 2)} crore</b></div>
      </div>
      <p className="sim-note">
        Cutting receivable days by ten would release about ₹{fmt((rev * 1e7 / 365) * 10 / 1e7, 2)} crore
        permanently, without a single extra sale. Paying suppliers later does the same, at the cost of
        the relationship. This is the cheapest capital most businesses never raise.
      </p>
    </div>
  );
}


/* ---- Yield curve: drag the shape, read what it implies ----------------- */
function SimYieldCurve() {
  const [shape, setShape] = useState("normal");
  const shapes = {
    normal: { name: "Normal", pts: [6.2, 6.6, 6.9, 7.1, 7.3, 7.45, 7.55],
      says: "Longer money costs more, which is the usual state. Investors want extra yield for locking funds away and for the inflation risk that comes with time." },
    flat: { name: "Flat", pts: [7.0, 7.05, 7.05, 7.1, 7.1, 7.1, 7.12],
      says: "Short and long yields have converged. Typically a transition, where the market is uncertain whether rates are near their peak." },
    inverted: { name: "Inverted", pts: [7.6, 7.4, 7.15, 6.95, 6.8, 6.7, 6.65],
      says: "Short money costs more than long. The market expects rates to fall, which usually means it expects growth to weaken. Historically this has often preceded recessions, though not always and not on a schedule." },
    steep: { name: "Steep", pts: [5.6, 6.2, 6.8, 7.3, 7.8, 8.1, 8.3],
      says: "A wide gap between short and long. Often follows aggressive rate cuts, with the market expecting recovery and higher inflation later." },
  };
  const cur = shapes[shape];
  const labels = ["3m", "1y", "2y", "5y", "10y", "20y", "30y"];
  const W = 620, H = 210, pad = 42;
  const lo = 5.2, hi = 8.6;
  const X = (i) => pad + (i / (cur.pts.length - 1)) * (W - pad * 2);
  const Y = (v) => H - pad - ((v - lo) / (hi - lo)) * (H - pad * 2);
  const line = cur.pts.map((v, i) => `${i ? "L" : "M"}${X(i).toFixed(1)} ${Y(v).toFixed(1)}`).join(" ");
  const spread = cur.pts[4] - cur.pts[0];

  return (
    <div className="sim">
      <div className="art-tabs" role="tablist">
        {Object.entries(shapes).map(([k, v]) => (
          <button key={k} role="tab" aria-selected={shape === k}
            className={"tab" + (shape === k ? " on" : "")} onClick={() => setShape(k)}>{v.name}</button>
        ))}
      </div>
      <svg viewBox={`0 0 ${W} ${H}`} className="sim-svg" role="img" aria-label="Yield curve shape">
        {[6, 7, 8].map((g) => (
          <g key={g}>
            <line x1={pad} y1={Y(g)} x2={W - pad} y2={Y(g)} className="sim-grid" />
            <text x={pad - 8} y={Y(g) + 4} textAnchor="end" className="sim-lab">{g}%</text>
          </g>
        ))}
        <path d={line} className="yc-line" />
        {cur.pts.map((v, i) => (
          <g key={i}>
            <circle cx={X(i)} cy={Y(v)} r="4.5" className="yc-dot" />
            <text x={X(i)} y={H - pad + 18} textAnchor="middle" className="sim-lab">{labels[i]}</text>
          </g>
        ))}
      </svg>
      <div className="sim-out">
        <div><span>3 month yield</span><b>{fmt(cur.pts[0], 2)}%</b></div>
        <div><span>10 year yield</span><b>{fmt(cur.pts[4], 2)}%</b></div>
        <div><span>Spread</span>
          <b className={spread < 0 ? "bad" : "hi"}>{spread >= 0 ? "+" : ""}{fmt(spread * 100, 0)} bps</b></div>
      </div>
      <p className="sim-note">{cur.says}</p>
    </div>
  );
}

/* ---- Money creation: a deposit becoming loans becoming deposits -------- */
function SimMoneyCreation() {
  const [reserve, setReserve] = useState(12);
  const rounds = 8;
  const start = 100000;
  const rows = [];
  let dep = start, total = 0;
  for (let i = 0; i < rounds; i++) {
    const held = dep * (reserve / 100);
    const lent = dep - held;
    rows.push({ i, dep, held, lent });
    total += dep;
    dep = lent;
  }
  const theoretical = start / (reserve / 100);
  return (
    <div className="sim">
      <Slider label="Reserve requirement" value={reserve} set={setReserve} min={4} max={30} suffix="%" />
      <div className="mc-stack">
        {rows.map((r) => (
          <div className="mc-row" key={r.i}>
            <span className="mc-n">{r.i === 0 ? "Original deposit" : `Round ${r.i}`}</span>
            <div className="mc-bar" style={{ width: `${(r.dep / start) * 100}%` }}>
              <span className="mc-held" style={{ width: `${reserve}%` }} />
            </div>
            <b>₹{fmt(r.dep, 0)}</b>
          </div>
        ))}
      </div>
      <div className="sim-out">
        <div><span>Original deposit</span><b>₹{fmt(start)}</b></div>
        <div><span>Deposits after {rounds} rounds</span><b className="hi">₹{fmt(total, 0)}</b></div>
        <div><span>Theoretical maximum</span><b>₹{fmt(theoretical, 0)}</b></div>
      </div>
      <p className="sim-note">
        One deposit of ₹1,00,000 has become ₹{fmt(total, 0)} of deposits across the system, and it
        would approach ₹{fmt(theoretical, 0)} if the process continued. No money was printed. Each
        loan created a deposit, and that deposit funded the next loan. This is how most money in a
        modern economy comes into existence, and why credit contraction destroys money just as fast.
      </p>
    </div>
  );
}

/* ---- Bank run: the moment it becomes self-fulfilling ------------------- */
function SimBankRun() {
  const [withdrawn, setWithdrawn] = useState(0);
  const deposits = 1000, reserves = 120, loans = 940, equity = 60;
  const cashLeft = Math.max(0, reserves - withdrawn);
  const shortfall = Math.max(0, withdrawn - reserves);
  const firesale = shortfall > 0 ? shortfall / 0.7 : 0;
  const loss = firesale > 0 ? firesale * 0.3 : 0;
  const solvent = loss < equity;
  const pct = (withdrawn / deposits) * 100;

  return (
    <div className="sim">
      <Slider label="Depositors withdrawing" value={withdrawn} set={setWithdrawn} min={0} max={600} step={10}
        suffix=" crore" />
      <div className="br-bars">
        <div className="br-bar">
          <span className="br-lab">Cash reserves</span>
          <div className="br-track">
            <div className="br-fill cash" style={{ width: `${(cashLeft / reserves) * 100}%` }} />
          </div>
          <b className={cashLeft === 0 ? "bad" : ""}>₹{fmt(cashLeft, 0)} cr</b>
        </div>
        <div className="br-bar">
          <span className="br-lab">Loans, not sellable quickly</span>
          <div className="br-track"><div className="br-fill loan" style={{ width: "100%" }} /></div>
          <b>₹{fmt(loans, 0)} cr</b>
        </div>
        <div className="br-bar">
          <span className="br-lab">Equity absorbing losses</span>
          <div className="br-track">
            <div className={"br-fill eq" + (solvent ? "" : " gone")}
              style={{ width: `${Math.max(0, (1 - loss / equity)) * 100}%` }} />
          </div>
          <b className={solvent ? "" : "bad"}>₹{fmt(Math.max(0, equity - loss), 0)} cr</b>
        </div>
      </div>
      <div className={"br-state " + (shortfall === 0 ? "ok" : solvent ? "warn" : "fail")}>
        {shortfall === 0
          ? `${fmt(pct, 0)}% withdrawn. Reserves are covering it. Nothing visible is wrong.`
          : solvent
            ? `Reserves are exhausted. To pay depositors the bank must sell ₹${fmt(firesale, 0)} crore of loans at a discount, losing ₹${fmt(loss, 0)} crore. Equity is absorbing it, for now.`
            : `Losses of ₹${fmt(loss, 0)} crore exceed equity of ₹${fmt(equity, 0)} crore. The bank is now insolvent — not because the loans were bad, but because they had to be sold at once.`}
      </div>
      <p className="sim-note">
        Every depositor withdrawing is individually rational. Collectively they cause the failure they
        feared. Nothing about the loan book changed at any point in this simulation. Deposit insurance
        exists to make the first withdrawal unnecessary, which is why it rarely has to pay out.
      </p>
    </div>
  );
}


/* ---- Option greeks: each force moving the premium separately ----------- */
function SimGreeks() {
  const [spot, setSpot] = useState(24000);
  const [days, setDays] = useState(20);
  const [vol, setVol] = useState(14);
  const strike = 24000, lot = 75;

  const T = Math.max(0.5, days) / 365;
  const sig = vol / 100;
  const d1 = (Math.log(spot / strike) + (0.5 * sig * sig) * T) / (sig * Math.sqrt(T));
  const d2 = d1 - sig * Math.sqrt(T);
  const N = (x) => {
    const t = 1 / (1 + 0.2316419 * Math.abs(x));
    const p = 0.3989423 * Math.exp(-x * x / 2) *
      (t * (0.3193815 + t * (-0.3565638 + t * (1.781478 + t * (-1.821256 + t * 1.330274)))));
    return x >= 0 ? 1 - p : p;
  };
  const call = spot * N(d1) - strike * N(d2);
  const delta = N(d1);
  const gamma = Math.exp(-d1 * d1 / 2) / (2.5066 * spot * sig * Math.sqrt(T));
  const theta = -(spot * (Math.exp(-d1 * d1 / 2) / 2.5066) * sig) / (2 * Math.sqrt(T)) / 365;
  const vega = spot * (Math.exp(-d1 * d1 / 2) / 2.5066) * Math.sqrt(T) / 100;

  const forces = [
    { k: "Delta", v: fmt(delta, 3), s: "Per 1 point the index moves",
      x: `The premium moves about ₹${fmt(delta, 2)} for each point. Read loosely, the market is pricing roughly a ${fmt(delta * 100, 0)}% chance of finishing in the money.` },
    { k: "Gamma", v: fmt(gamma * 1000, 3), s: "How fast delta itself changes",
      x: "Largest near the strike and near expiry. This is where a position becomes unstable, because your exposure changes as the price moves." },
    { k: "Theta", v: fmt(theta, 2), s: "Lost each day to time passing",
      x: `About ₹${fmt(Math.abs(theta) * lot, 0)} per lot per day, with nothing moving. For a buyer this is a daily cost. For a seller it is daily income.` },
    { k: "Vega", v: fmt(vega, 2), s: "Per 1 point of implied volatility",
      x: "Both calls and puts gain when expected volatility rises. This is why an option can lose money after a correct directional call, if volatility falls at the same time." },
  ];

  return (
    <div className="sim">
      <Slider label="Underlying" value={spot} set={setSpot} min={22800} max={25200} step={25} />
      <Slider label="Days to expiry" value={days} set={setDays} min={1} max={45} />
      <Slider label="Implied volatility" value={vol} set={setVol} min={8} max={34} suffix="%" />
      <div className="gk-premium">
        <span>Call premium, strike {fmt(strike, 0)}</span>
        <b><Counter value={call} prefix="₹" decimals={2} /></b>
        <em>₹{fmt(call * lot, 0)} per lot of {lot}</em>
      </div>
      <div className="gk-grid">
        {forces.map((f) => (
          <div className="gk-card" key={f.k}>
            <div className="gk-top"><span>{f.k}</span><b>{f.v}</b></div>
            <p className="gk-s">{f.s}</p>
            <p className="gk-x">{f.x}</p>
          </div>
        ))}
      </div>
      <p className="sim-note">
        Drag days to expiry from {days} down to 1 without touching anything else. The premium falls
        while the index has not moved at all. That is theta, and it is why buying options and waiting
        is a losing strategy even when the view is right.
      </p>
    </div>
  );
}

/* ---- Terminal value dominating a valuation ---------------------------- */
function SimTerminalValue() {
  const [growth, setGrowth] = useState(4);
  const [wacc, setWacc] = useState(11);
  const [years, setYears] = useState(10);
  const fcf0 = 80;
  const g = growth / 100, r = Math.max(growth / 100 + 0.005, wacc / 100);
  let explicit = 0, cf = fcf0;
  for (let y = 1; y <= years; y++) { cf = cf * 1.08; explicit += cf / Math.pow(1 + r, y); }
  const tv = (cf * (1 + g)) / (r - g);
  const pvTv = tv / Math.pow(1 + r, years);
  const total = explicit + pvTv;
  const share = (pvTv / total) * 100;

  return (
    <div className="sim">
      <Slider label="Perpetual growth" value={growth} set={setGrowth} min={0} max={7} step={0.5} suffix="%" />
      <Slider label="Discount rate" value={wacc} set={setWacc} min={7} max={18} step={0.5} suffix="%" />
      <Slider label="Forecast years" value={years} set={setYears} min={5} max={20} />
      <div className="tv-split">
        <div className="tv-seg forecast" style={{ width: `${100 - share}%` }}>
          <span>Forecast years</span><b>{fmt(100 - share, 0)}%</b>
        </div>
        <div className="tv-seg terminal" style={{ width: `${share}%` }}>
          <span>Beyond the forecast</span><b>{fmt(share, 0)}%</b>
        </div>
      </div>
      <div className="sim-out">
        <div><span>Value from {years} forecast years</span><b>₹{fmt(explicit, 0)} cr</b></div>
        <div><span>Value from everything after</span><b className={share > 65 ? "bad" : ""}>₹{fmt(pvTv, 0)} cr</b></div>
        <div><span>Total</span><b className="hi">₹{fmt(total, 0)} cr</b></div>
      </div>
      <p className="sim-note">
        {fmt(share, 0)}% of this valuation comes from a period nobody forecast. Raise perpetual growth
        by one point and watch that share climb. This is the uncomfortable truth of discounted cash
        flow: most of the answer rests on two assumptions about a future beyond anyone's sight, and
        the years modelled in detail matter least.
      </p>
    </div>
  );
}

/* ---- Alpha and beta ---------------------------------------------------- */
function SimAlphaBeta() {
  const [beta, setBeta] = useState(1.2);
  const [alpha, setAlpha] = useState(2);
  const rf = 6.5, mkt = 12;
  const expected = rf + beta * (mkt - rf);
  const actual = expected + alpha;
  const W = 600, H = 200, pad = 40;
  const xs = [-20, -10, 0, 10, 20, 30];
  const X = (m) => pad + ((m + 20) / 50) * (W - pad * 2);
  const Y = (v) => H - pad - ((v + 30) / 90) * (H - pad * 2);
  const capm = xs.map((m, i) => `${i ? "L" : "M"}${X(m)} ${Y(rf + beta * (m - rf))}`).join(" ");
  const withA = xs.map((m, i) => `${i ? "L" : "M"}${X(m)} ${Y(rf + beta * (m - rf) + alpha)}`).join(" ");

  return (
    <div className="sim">
      <Slider label="Beta, sensitivity to the market" value={beta} set={setBeta} min={0.2} max={2.2} step={0.1} />
      <Slider label="Alpha, return beyond what beta explains" value={alpha} set={setAlpha} min={-6} max={8} step={0.5} suffix="%" />
      <svg viewBox={`0 0 ${W} ${H}`} className="sim-svg" role="img" aria-label="Alpha and beta">
        <line x1={pad} y1={Y(0)} x2={W - pad} y2={Y(0)} className="sim-axis" />
        <line x1={X(0)} y1={pad} x2={X(0)} y2={H - pad} className="sim-axis" />
        <path d={capm} className="ab-capm" />
        <path d={withA} className="ab-actual" />
        <circle cx={X(mkt)} cy={Y(actual)} r="5" className="sim-dot comp" />
        <text x={W - pad} y={Y(0) + 16} textAnchor="end" className="sim-lab">Market return →</text>
        <text x={pad + 6} y={pad + 4} className="sim-lab">Portfolio return</text>
      </svg>
      <div className="sim-out">
        <div><span>Beta</span><b>{fmt(beta, 1)}</b></div>
        <div><span>Return beta alone predicts</span><b>{fmt(expected, 1)}%</b></div>
        <div><span>Alpha</span><b className={alpha >= 0 ? "hi" : "bad"}>{alpha >= 0 ? "+" : ""}{fmt(alpha, 1)}%</b></div>
        <div><span>Actual return</span><b className="hi">{fmt(actual, 1)}%</b></div>
      </div>
      <p className="sim-note">
        A beta of {fmt(beta, 1)} means the portfolio should return {fmt(expected, 1)}% when the market
        returns {mkt}%. Anything beyond that is alpha. Set beta to 2.0 and the return rises without any
        skill involved, which is why a high return alone proves nothing. Alpha is what remains after
        the risk taken is accounted for, and it is far rarer than it appears.
      </p>
    </div>
  );
}


/* ===========================================================================
   VALUATION
   A discounted cash flow built in front of you, stage by stage. The point is
   not the answer but the sensitivity: watching how much a valuation moves on
   assumptions nobody can verify is the fastest way to learn what a DCF is
   actually worth.
   =========================================================================== */

function SimDCF() {
  const [model, setModel] = useState("two");
  const [fcf0, setFcf0] = useState(100);
  const [g1, setG1] = useState(18);
  const [n1, setN1] = useState(5);
  const [g2, setG2] = useState(9);
  const [n2, setN2] = useState(5);
  const [gT, setGT] = useState(4);
  const [wacc, setWacc] = useState(11);
  const [debt, setDebt] = useState(240);
  const [cash, setCash] = useState(60);
  const [shares, setShares] = useState(10);

  const r = Math.max(gT / 100 + 0.005, wacc / 100);
  const rows = [];
  let cf = fcf0;

  if (model === "one") {
    for (let y = 1; y <= n1; y++) { cf *= 1 + g1 / 100; rows.push({ y, cf, stage: 1 }); }
  } else if (model === "two") {
    for (let y = 1; y <= n1; y++) { cf *= 1 + g1 / 100; rows.push({ y, cf, stage: 1 }); }
    for (let y = n1 + 1; y <= n1 + n2; y++) { cf *= 1 + g2 / 100; rows.push({ y, cf, stage: 2 }); }
  } else {
    for (let y = 1; y <= n1; y++) { cf *= 1 + g1 / 100; rows.push({ y, cf, stage: 1 }); }
    const steps = n2;
    for (let k = 1; k <= steps; k++) {
      const gk = g1 + ((gT - g1) * k) / steps;
      cf *= 1 + gk / 100;
      rows.push({ y: n1 + k, cf, stage: 2, g: gk });
    }
  }

  const pvRows = rows.map((x) => ({ ...x, pv: x.cf / Math.pow(1 + r, x.y) }));
  const explicit = pvRows.reduce((a, x) => a + x.pv, 0);
  const lastCf = rows[rows.length - 1].cf;
  const N = rows.length;
  const tv = (lastCf * (1 + gT / 100)) / (r - gT / 100);
  const pvTv = tv / Math.pow(1 + r, N);
  const ev = explicit + pvTv;
  const equity = ev - debt + cash;
  const perShare = shares > 0 ? equity / shares : 0;
  const tvShare = (pvTv / ev) * 100;

  // sensitivity: value per share across wacc and terminal growth
  const waccs = [wacc - 1, wacc, wacc + 1];
  const gs = [gT - 1, gT, gT + 1];
  const grid = waccs.map((w) => gs.map((g) => {
    const rr = Math.max(g / 100 + 0.005, w / 100);
    const ex = rows.reduce((a, x) => a + x.cf / Math.pow(1 + rr, x.y), 0);
    const t2 = (lastCf * (1 + g / 100)) / (rr - g / 100) / Math.pow(1 + rr, N);
    return shares > 0 ? (ex + t2 - debt + cash) / shares : 0;
  }));

  const W = 660, H = 190, pad = 38;
  const maxPv = Math.max(...pvRows.map((x) => x.pv), 1);
  const bw = (W - pad * 2) / Math.max(1, pvRows.length) - 4;

  return (
    <div className="sim">
      <div className="art-tabs" role="tablist" aria-label="Model">
        {[["one", "Single stage"], ["two", "Two stage"], ["three", "Three stage, fading"]].map(([k, l]) => (
          <button key={k} role="tab" aria-selected={model === k}
            className={"tab" + (model === k ? " on" : "")} onClick={() => setModel(k)}>{l}</button>
        ))}
      </div>

      <p className="sim-note" style={{ marginTop: 12, marginBottom: 16 }}>
        {model === "one"
          ? "One growth rate, then perpetuity. Simple, and it assumes a company grows at the same rate until the day it stops, which no company does."
          : model === "two"
            ? "High growth first, then a lower second phase, then perpetuity. The standard structure, and it assumes growth drops in a single step."
            : "Growth fades gradually from the high rate toward the terminal rate. The most realistic shape, because competition erodes advantage slowly rather than all at once."}
      </p>

      <div className="dcf-inputs">
        <label className="tkf"><span>Free cash flow now, ₹ cr</span>
          <input type="number" value={fcf0} onChange={(e) => setFcf0(Math.max(1, Number(e.target.value)))} /></label>
        <label className="tkf"><span>Net debt, ₹ cr</span>
          <input type="number" value={debt} onChange={(e) => setDebt(Math.max(0, Number(e.target.value)))} /></label>
        <label className="tkf"><span>Cash, ₹ cr</span>
          <input type="number" value={cash} onChange={(e) => setCash(Math.max(0, Number(e.target.value)))} /></label>
        <label className="tkf"><span>Shares, crore</span>
          <input type="number" value={shares} onChange={(e) => setShares(Math.max(0.1, Number(e.target.value)))} /></label>
      </div>

      <Slider label={model === "three" ? "Starting growth" : "Stage one growth"} value={g1} set={setG1} min={0} max={40} suffix="%" />
      <Slider label="Stage one years" value={n1} set={setN1} min={2} max={12} />
      {model === "two" && <Slider label="Stage two growth" value={g2} set={setG2} min={0} max={25} suffix="%" />}
      {model !== "one" && <Slider label={model === "three" ? "Fade years" : "Stage two years"} value={n2} set={setN2} min={2} max={15} />}
      <Slider label="Terminal growth, forever" value={gT} set={setGT} min={0} max={7} step={0.5} suffix="%" />
      <Slider label="Discount rate, WACC" value={wacc} set={setWacc} min={7} max={20} step={0.5} suffix="%" />

      <svg viewBox={`0 0 ${W} ${H}`} className="sim-svg" role="img"
        aria-label="Present value of each forecast year">
        {pvRows.map((x, i) => {
          const h = (x.pv / maxPv) * (H - pad * 2);
          return (
            <g key={i}>
              <rect x={pad + i * (bw + 4)} y={H - pad - h} width={bw} height={h} rx="3"
                className={"dcf-bar s" + x.stage} />
              <text x={pad + i * (bw + 4) + bw / 2} y={H - pad + 14} textAnchor="middle"
                className="sim-lab">{x.y}</text>
            </g>
          );
        })}
        <text x={pad} y={pad - 8} className="sim-lab">Present value of each year, ₹ cr</text>
      </svg>

      <div className="dcf-split">
        <div className="dcf-seg forecast" style={{ width: `${100 - tvShare}%` }}>
          <span>Forecast years</span><b>{fmt(100 - tvShare, 0)}%</b>
        </div>
        <div className="dcf-seg terminal" style={{ width: `${tvShare}%` }}>
          <span>Terminal value</span><b>{fmt(tvShare, 0)}%</b>
        </div>
      </div>

      <div className="sim-out">
        <div><span>Enterprise value</span><b>₹{fmt(ev, 0)} cr</b></div>
        <div><span>Equity value</span><b>₹{fmt(equity, 0)} cr</b></div>
        <div><span>Value per share</span><b className="hi">₹{fmt(perShare, 2)}</b></div>
      </div>

      <div className="dcf-sens">
        <p className="eyebrow" style={{ marginBottom: 10 }}>Value per share, if the two assumptions move</p>
        <div className="dcf-grid">
          <span className="dcf-corner">WACC ↓ / g →</span>
          {gs.map((g) => <span key={g} className="dcf-h">{fmt(g, 1)}%</span>)}
          {waccs.map((w, i) => (
            <React.Fragment key={w}>
              <span className="dcf-h">{fmt(w, 1)}%</span>
              {grid[i].map((v, j) => (
                <span key={j} className={"dcf-cell" + (i === 1 && j === 1 ? " mid" : "")}>
                  ₹{fmt(v, 0)}
                </span>
              ))}
            </React.Fragment>
          ))}
        </div>
        <p className="sim-note" style={{ marginTop: 12 }}>
          One percentage point either way on each assumption moves the answer from
          ₹{fmt(Math.min(...grid.flat()), 0)} to ₹{fmt(Math.max(...grid.flat()), 0)} per share, a range of
          {" "}{fmt(((Math.max(...grid.flat()) / Math.max(0.01, Math.min(...grid.flat()))) - 1) * 100, 0)}%.
          Neither assumption can be verified. This is why a serious valuation reports a range and its
          sensitivity, and why a single precise number should be treated with suspicion.
        </p>
      </div>
    </div>
  );
}

const SIMS = {
  dcf: { title: "Build a discounted cash flow and watch it move", el: SimDCF },
  greeks: { title: "Move one force at a time and watch the premium respond", el: SimGreeks },
  terminalvalue: { title: "See how much of a valuation sits beyond the forecast", el: SimTerminalValue },
  alphabeta: { title: "Separate the return you took risk for from the rest", el: SimAlphaBeta },
  yieldcurve: { title: "Change the shape and read what it implies", el: SimYieldCurve },
  moneycreation: { title: "Watch one deposit become many", el: SimMoneyCreation },
  bankrun: { title: "Withdraw, and watch a sound bank fail", el: SimBankRun },
  inflation: { title: "Watch a fixed sum lose what it can buy", el: SimInflation },
  statements: { title: "One sale, followed through all three statements", el: SimStatements },
  workingcapital: { title: "Move the cycle and watch cash free up", el: SimWorkingCapital },
  payments: { title: "Send the same payment three ways and watch where the time goes", el: SimPayments },
  ratios: { title: "Change any figure and watch every ratio move", el: SimRatios },
  options: { title: "Move the strike and premium, and watch the payoff bend", el: SimOptions },
  diversification: { title: "Move the correlation, and watch the combined line flatten", el: SimDiversification },
  siplump: { title: "Same money, two methods, three different markets", el: SimSipLumpsum },
  compounding: { title: "Watch compounding separate from simple interest", el: SimCompounding },
  leverage: { title: "Move the leverage and watch equity absorb the loss", el: SimLeverage },
  bond: { title: "Move the yield and watch the price respond", el: SimBond },
};

function NumField({ label, value, set, suffix, step = "any", min = 0 }) {
  return (
    <div className="field">
      <label>{label}{suffix ? ` (${suffix})` : ""}</label>
      <input type="number" inputMode="decimal" step={step} min={min} value={value}
        onChange={(e) => set(e.target.value)} />
    </div>
  );
}

function Calc({ id }) {
  const [a, setA] = useState(id === "sip" ? 5000 : id === "loan" ? 2500000 : 100000);
  const [b, setB] = useState(id === "loan" ? 8.5 : id === "cagr" ? 250000 : 8);
  const [c, setC] = useState(id === "cagr" ? 5 : id === "compound" ? 5 : 10);
  const [d, setD] = useState(1); // compounding frequency / inflation

  let rows = [], note = "";
  if (id === "sip") {
    const P = +a, i = +b / 100 / 12, n = +c * 12;
    const fv = i === 0 ? P * n : P * ((Math.pow(1 + i, n) - 1) / i) * (1 + i);
    const inv = P * n;
    rows = [["Total invested", `₹${fmt(inv)}`], ["Estimated value", `₹${fmt(fv)}`], ["Growth", `₹${fmt(fv - inv)}`]];
    note = "Assumes a constant return and investment at the start of each month. Market returns are not constant.";
  } else if (id === "compound") {
    const P = +a, r = +b / 100, m = Math.max(1, +d), t = +c;
    const A = P * Math.pow(1 + r / m, m * t);
    const ear = (Math.pow(1 + r / m, m) - 1) * 100;
    rows = [["Final amount", `₹${fmt(A)}`], ["Interest earned", `₹${fmt(A - P)}`], ["Effective annual rate", `${fmt(ear, 2)}%`]];
    note = "Compounding frequency of 1 is annual, 4 quarterly, 12 monthly.";
  } else if (id === "cagr") {
    const s = +a, e = +b, y = +c;
    const g = y > 0 && s > 0 ? (Math.pow(e / s, 1 / y) - 1) * 100 : NaN;
    rows = [["CAGR", `${fmt(g, 2)}%`], ["Total change", `${fmt(((e - s) / s) * 100, 2)}%`]];
    note = "CAGR smooths the path into one constant rate. It says nothing about the volatility along the way.";
  } else if (id === "loan") {
    const P = +a, i = +b / 100 / 12, n = +c * 12;
    const emi = i === 0 ? P / n : (P * i * Math.pow(1 + i, n)) / (Math.pow(1 + i, n) - 1);
    const total = emi * n;
    rows = [["Monthly EMI", `₹${fmt(emi)}`], ["Total repayment", `₹${fmt(total)}`], ["Total interest", `₹${fmt(total - P)}`],
    ["Interest as % of principal", `${fmt(((total - P) / P) * 100, 1)}%`]];
    note = "The EMI is set so that the present value of all payments equals the amount borrowed today.";
  } else if (id === "real") {
    const nom = +b / 100, inf = +d / 100;
    const real = ((1 + nom) / (1 + inf) - 1) * 100;
    const approx = (+b - +d);
    rows = [["Real return (exact)", `${fmt(real, 2)}%`], ["Approximation (nominal − inflation)", `${fmt(approx, 2)}%`],
    ["Value of ₹1,00,000 after 10 years, in today's money", `₹${fmt(100000 * Math.pow(1 + real / 100, 10))}`]];
    note = "The approximation drifts from the exact figure as rates rise.";
  }

  const fields = {
    sip: [["Monthly investment", a, setA, "₹"], ["Expected annual return", b, setB, "%"], ["Duration", c, setC, "years"]],
    compound: [["Principal", a, setA, "₹"], ["Annual rate", b, setB, "%"], ["Years", c, setC, ""], ["Compounding per year", d, setD, ""]],
    cagr: [["Starting value", a, setA, "₹"], ["Ending value", b, setB, "₹"], ["Years", c, setC, ""]],
    loan: [["Loan amount", a, setA, "₹"], ["Annual interest rate", b, setB, "%"], ["Tenure", c, setC, "years"]],
    real: [["Nominal return", b, setB, "%"], ["Inflation", d, setD, "%"]],
  }[id];

  const tool = TOOLS.find((t) => t.id === id);
  return (
    <div className="grid g2" style={{ gap: 28 }}>
      <div>
        {fields.map(([l, v, s, suf]) => <NumField key={l} label={l} value={v} set={s} suffix={suf} />)}
      </div>
      <div className="card" style={{ height: "max-content" }}>
        <p className="kicker">Result</p>
        <div className="out" style={{ marginTop: 14 }}>
          {rows.map(([k, v]) => (
            <div className="outrow" key={k}><span className="small">{k}</span><b style={{ color: "var(--aqua)" }}>{v}</b></div>
          ))}
        </div>
        <p className="small" style={{ marginTop: 16, fontSize: 12.5 }}>{note}</p>
        {tool && conceptById(tool.concept) && (
          <a className="chip" href={`#/concept/${tool.concept}`} style={{ marginTop: 16, display: "inline-block" }}>
            The concept behind this: {conceptById(tool.concept).title} →
          </a>
        )}
      </div>
    </div>
  );
}

